import { ethers } from "ethers";
import * as fs from "fs";
import * as path from "path";

async function main() {
  const envPath = path.resolve(__dirname, "../.env");

  if (fs.existsSync(envPath)) {
    console.log("A .env file already exists! Aborting to avoid overwriting existing keys.");
    return;
  }

  // Generate a cryptographically secure random testnet wallet
  const wallet = ethers.Wallet.createRandom();

  const envContent = `# ==============================================================================
# MiniBridge Testnet Environment (.env)
# AUTOGENERATED TESTNET WALLET - DO NOT USE FOR REAL ASSETS
# ==============================================================================

# Public RPC Endpoints
SEPOLIA_RPC_URL="https://ethereum-sepolia-rpc.publicnode.com"
AMOY_RPC_URL="https://rpc-amoy.polygon.technology"

# Generated Testnet Wallet (Used for both deployer and relayer on testnets)
DEPLOYER_PRIVATE_KEY="${wallet.privateKey}"
RELAYER_PRIVATE_KEY="${wallet.privateKey}"

# Contract Addresses (will be automatically filled upon deployment)
SEPOLIA_TEST_TOKEN_ADDRESS=""
SEPOLIA_BRIDGE_SOURCE_ADDRESS=""
AMOY_WRAPPED_TOKEN_ADDRESS=""
AMOY_BRIDGE_DESTINATION_ADDRESS=""

# Relayer Parameters
CONFIRMATIONS_SEPOLIA="2"
CONFIRMATIONS_AMOY="5"
POLL_INTERVAL_MS="5000"

ETHERSCAN_API_KEY=""
POLYGONSCAN_API_KEY=""
`;

  fs.writeFileSync(envPath, envContent, "utf8");

  console.log("====================================================");
  console.log(" NEW TESTNET WALLET GENERATED & SAVED TO .env");
  console.log("====================================================");
  console.log("PUBLIC ADDRESS (Share this with faucets):");
  console.log(wallet.address);
  console.log("====================================================");
  console.log("Your private key has been safely saved inside your local .env file.");
  console.log("Because .env is in .gitignore, it will NEVER be committed to GitHub.");
}

main().catch((err) => {
  console.error("Failed to generate wallet:", err);
  process.exit(1);
});

